head.script:
scwin.trigger1_onclick = function(e) {
    gridView1.setCellOption(2, "col1", "viewType", "default");
};
scwin.trigger2_onclick = function(e) {
    gridView1.setCellOption(2, "col1", "viewType", "icon");
};
scwin.checkVal1 = function() {
    return window.getComputedStyle(WebSquare.wUnit.getDomById($p.id + 'gridView1_cell_2_0')).getPropertyValue('background-image') == 'none';
}
scwin.checkVal2 = function() {
    return window.getComputedStyle(WebSquare.wUnit.getDomById($p.id + 'gridView1_cell_2_0')).getPropertyValue('background-image') != 'none';
}
scwin.unitTest = function() {
    //Unit test
    WebSquare.wUnit.start();
    //Test step 1. 샘플파일을 실행 후 setCellOption(2,'col1', 'viewType', 'default') 버튼을 클릭한다.- After running the sample file, click the setCellOption (2, 'col1', 'viewType', 'default') button.
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('trigger1').click()");
    WebSquare.wUnit.addCommand("pause", "1000");
    //Verify 1. 20160620일자 달력아이콘이 보이지 않는다.(이전에는 계속보여짐)-20160620 Calendar icon is not visible (Previously displayed)
    WebSquare.wUnit.addCommand("assert", "scwin.checkVal1()", "true");
    WebSquare.wUnit.addCommand("pause", "1000");
    //Test step 2. 다시 setCellOption(2,'col1', 'viewType', 'icon') 버튼을 클릭한다.-Click the setCellOption (2, 'col1', 'viewType', 'icon') button again.
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('trigger2').click()");
    WebSquare.wUnit.addCommand("pause", "1000");
    //Verify 2. 20160620일자 달력아이콘이 보여진다.- The 20160620 date calendar icon is displayed.
    WebSquare.wUnit.addCommand("assert", "scwin.checkVal2()", "true");
    WebSquare.wUnit.addCommand("pause", "1000");
    //Run and Stop test
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.onpageload2 = function() {
    if (typeof scwin.onpageload === "function") {
        scwin.onpageload();
    }
    window.s1 = 20160618;
    window.s2 = 0;
    window.s3 = 1000;
    window.data = [];
    for (var i = 0; i < 10; i++) {
        data.push(s1 + i);
        data.push(s2 + i);
        data.push(s3 - i);
    }
    dataList1.setData(data);
    //Function unitTest
    //Create by Truong.Luu
    //Create date 18-Jan-2018
    //End unitTest
    if (typeof scwin.unitTest === "function") {
        scwin.unitTest();
    }
}
